const fn = new Function(code + "\nreturn { fetchAllPages };");
const { fetchAllPages } = fn();
const pages = { 1: { items: ["a"], hasMore: true }, 2: { items: ["b"], hasMore: true }, 3: { items: ["c"], hasMore: false } };
let requested = [];
const out = await fetchAllPages(async (n) => { requested.push(n); return pages[n]; }, 10);
if (out.join() !== "a,b,c") throw new Error("All three pages' items in order.");
if (requested.join() !== "1,2,3") throw new Error("Pages 1..3 requested in order — page 3 said hasMore: false so stop.");

const fn = new Function(code + "\nreturn { fetchAllPages };");
const { fetchAllPages } = fn();
const endless = async (n) => ({ items: [n], hasMore: true });
let calls = 0;
const wrapped = async (n) => { calls++; return endless(n); };
const out = await fetchAllPages(wrapped, 5);
if (calls !== 5) throw new Error("With hasMore always true, exactly maxPages pages may be fetched.");
if (out.length !== 5) throw new Error("Five items collected.");
